+            application->run();
+        } catch (...) {
+            holo_iface->stop();
+            throw;
+        }
+        holo_iface->stop();
+        return 0;
+    } catch (const std::exception& e) {
+        HOLOSCAN_LOG_ERROR("Application failed: {}", e.what());
+        return -1;
+    }
