+                if (s_id != Ar0234::DEV_ID) {
+                    throw std::runtime_error(fmt::format(
+                        "Sensor mismatch at i2c=0x{:02X}: expected 0x{:04X}, got 0x{:04X}",
+                        s->get_i2c_address(), Ar0234::DEV_ID, s_id));
