+            application->run();
+        } catch (...) {
+            holo_iface->stop();
+            std::cout << "Stereo skew: " << skew_state.summary() << std::endl;
+            g_skew_state = nullptr; // suppress duplicate from terminate handler
+            throw;
+        }
