+        std::cout << "Stereo skew: " << skew_state.summary() << std::endl;
+        g_skew_state = nullptr;
+        return 0;
+    } catch (const std::exception& e) {
+        HOLOSCAN_LOG_ERROR("Application failed: {}", e.what());
+        return -1;
+    }
+}

